/* js/data/courses_plus.js — chapitres supplémentaires (COURS) et leçons détaillées (LESSONS, plusieurs par matière) */

const les=(t,b)=>[t,b+`<p style="text-align:center"><button class="btn p" onclick="toggleLes()">Passer au quiz →</button></p>`];
LESSONS.mon=[LESSONS.mon];

/* CHAPTERS[id] : chapitres du programme ; chaque chapitre regroupe des leçons (indices dans LESSONS[id]). Voir CONTEXT.md §4 */
const CHAPTERS={};

/* ============ TES – Équipements vidéo ============ */
COURS.tes.push(
["Optique & exposition",["f/ = rapport focale/diamètre ; chaque cran (1 stop) double ou divise la lumière : f/1,4 – 2 – 2,8 – 4 – 5,6 – 8 – 11 – 16.","T-stop = transmission réelle (objectifs cinéma) ; filtre ND = moins de lumière sans changer l’ouverture.","Zébras, false colors, histogramme : outils de contrôle de l’exposition."]],
["Numérisation de l’image",["Définitions : SD 720×576, HD 1280×720, Full HD 1920×1080, UHD 3840×2160, 4K DCI 4096×2160.","Sous-échantillonnage : 4:4:4 (aucune perte de chroma), 4:2:2 (chroma /2 en horizontal), 4:2:0 (chroma /2 en horizontal et vertical).","8 bits = 256 niveaux, 10 bits = 1 024 niveaux (moins de banding)."]],
["Codecs & conteneurs",["Intra-frame (ProRes, DNxHR) : chaque image est indépendante → idéal montage.","Inter-frame / GOP (H.264, H.265, XAVC LongGOP) : images I, P, B → léger mais plus lourd à décoder.","Conteneurs : MOV, MP4, MXF (broadcast/Avid), MKV."]],
["Stockage & réseau",["Taille (Mo) = débit (Mb/s) × durée (s) ÷ 8.","RAID 0 = vitesse sans sécurité ; RAID 1 = miroir ; RAID 5 = parité (1 panne tolérée).","Règle 3-2-1 : 3 copies, 2 supports, 1 copie hors site. Toujours vérifier la copie par checksum."]],
["Audio numérique",["48 kHz / 24 bits en vidéo ; dynamique ≈ 6 dB par bit.","0 dBFS = maximum numérique : au-delà, écrêtage (clipping).","EBU R128 : −23 LUFS, crête réelle max −1 dBTP."]],
["Timecode, synchro & couleur",["Timecode HH:MM:SS:FF ; drop frame uniquement en 29,97 / 59,94 i/s.","Genlock : synchronise les sources vidéo ; LTC : timecode transporté sur une piste audio.","Rec.709 (HD), Rec.2020 (UHD/HDR), DCI-P3 (cinéma), sRGB (web). Scopes : waveform, vectorscope, parade."]]
);
LESSONS.tes=[
les("📖 1. Caméra, capteur et optique",`<h3>Le capteur</h3><p>Le capteur transforme la lumière en signal électrique. Plus il est grand, plus il capte de lumière et plus la profondeur de champ est faible à cadrage et ouverture égaux. Formats courants : Micro 4/3 (≈ 17,3 × 13 mm), Super 35 (≈ 24,9 × 18,7 mm), Full Frame (36 × 24 mm).</p><ul><li><b>Dynamique :</b> exprimée en <i>stops</i> (diaphragmes). 14 stops = rapport de luminosité de 2<sup>14</sup>.</li><li><b>ISO natif :</b> sensibilité où le bruit est minimal ; au-delà, on amplifie le signal donc le bruit.</li><li><b>Rolling shutter :</b> lecture ligne par ligne, déformation sur mouvements rapides. <b>Global shutter :</b> lecture simultanée, pas de déformation.</li><li><b>Profil Log :</b> courbe aplatie qui préserve la dynamique ; demande un étalonnage ou une LUT.</li></ul><h3>L’obturateur</h3><p>Règle des 180° : vitesse = 1 / (2 × fps). À 25 i/s : 1/50 s. En Europe, cela évite aussi le <i>flicker</i> avec les lumières alimentées en 50 Hz.</p><h3>L’objectif</h3><ul><li><b>Monture</b> (PL, EF, E, MFT…) : compatibilité mécanique avec la caméra.</li><li><b>T-stop</b> : ouverture mesurée en lumière réellement transmise, utile pour égaliser un jeu d’objectifs.</li><li><b>Anamorphique :</b> compresse l’image horizontalement (à désétirer), flares horizontaux et bokeh ovale.</li><li><b>Filtre ND :</b> ND 0,3 = 1 stop, ND 0,6 = 2 stops, ND 0,9 = 3 stops.</li></ul><div class="note"><b>À retenir :</b> grande ouverture + grand capteur + longue focale = faible profondeur de champ.</div>`),
les("📖 2. Signal, échantillonnage et débit",`<h3>Résolution et cadence</h3><p>Full HD 1920×1080, UHD 3840×2160 (grand public), 4K DCI 4096×2160 (cinéma). Cadences : 24 i/s (cinéma), 25 i/s (TV Europe), 29,97 i/s (NTSC, en réalité 30000/1001), 50 i/s et 59,94 i/s pour la fluidité. Progressif (p) : image complète ; entrelacé (i) : deux demi-images (trames) par image, ex. 1080i50.</p><h3>Sous-échantillonnage de la chrominance</h3><p>L’œil est moins sensible à la couleur qu’à la luminance. On garde toute la luminance (Y) et on réduit la chrominance (Cb, Cr).</p><ul><li><b>4:4:4</b> : pleine résolution couleur.</li><li><b>4:2:2</b> : couleur divisée par 2 horizontalement (standard broadcast et montage).</li><li><b>4:2:0</b> : divisée par 2 en horizontal et vertical (diffusion, H.264 grand public).</li></ul><h3>Profondeur de bits</h3><p>8 bits = 256 niveaux par composante, 10 bits = 1 024, 12 bits = 4 096. Plus de bits = dégradés plus doux, étalonnage plus souple.</p><h3>Calculer un débit non compressé</h3><p>Débit = largeur × hauteur × images/s × bits par pixel.<br>Exemple 1080p25, 4:2:2, 10 bits (20 bits par pixel en moyenne) : 1920 × 1080 × 25 × 20 ≈ <b>1,04 Gb/s</b>.</p><div class="note"><b>Conversion :</b> 8 bits = 1 octet. 80 Mb/s = 10 Mo/s. Un flux de 100 Mb/s pendant 1 h : 100 × 3 600 ÷ 8 = 45 000 Mo ≈ <b>45 Go</b>.</div>`),
les("📖 3. Codecs, conteneurs et formats",`<h3>Codec ≠ conteneur</h3><p>Le <b>codec</b> compresse/décompresse l’image ou le son. Le <b>conteneur</b> est l’enveloppe qui regroupe vidéo, audio, timecode et métadonnées (MOV, MP4, MXF, MKV).</p><h3>Compression intra et inter</h3><ul><li><b>Intra-frame :</b> chaque image est codée seule (ProRes, DNxHR, XAVC Intra). Lourd en débit mais fluide au montage.</li><li><b>Inter-frame (GOP) :</b> images I (complètes), P (prédites), B (bidirectionnelles). H.264, H.265 : très légers, mais le décodage coûte du processeur.</li></ul><h3>Familles à connaître</h3><ul><li><b>Apple ProRes :</b> Proxy, LT, 422, 422 HQ, 4444 (avec canal alpha possible), 4444 XQ.</li><li><b>Avid DNxHD / DNxHR :</b> LB, SQ, HQ, HQX, 444.</li><li><b>MXF :</b> conteneur broadcast, utilisé nativement par Avid (OP-Atom).</li></ul><h3>Les 4 usages d’un codec</h3><ol><li><b>Tournage</b> (capture) : RAW, XAVC, ProRes RAW.</li><li><b>Montage</b> : ProRes, DNxHR (ou proxys).</li><li><b>Diffusion</b> : H.264, H.265.</li><li><b>Archivage</b> : fichiers mezzanine de haute qualité.</li></ol><div class="note">Transcoder en codec de montage ou créer des <b>proxys</b> permet de monter fluide sur des machines modestes, puis de reconnecter les originaux (conformation).</div>`),
les("📖 4. Stockage, sauvegarde et connectique",`<h3>Les supports</h3><ul><li><b>HDD</b> : capacité élevée, ~150 Mo/s, fragile.</li><li><b>SSD SATA</b> : ~500 Mo/s. <b>SSD NVMe</b> : plusieurs Go/s.</li></ul><h3>Interfaces</h3><ul><li>USB 3.x : 5 à 20 Gb/s selon la version.</li><li>Thunderbolt 3/4 : 40 Gb/s.</li><li>Ethernet 1 GbE / 10 GbE pour NAS et stockage partagé.</li></ul><h3>Liaisons vidéo</h3><ul><li><b>SDI</b> (connecteur BNC) : SD 270 Mb/s, HD 1,485 Gb/s, 3G 2,97 Gb/s, 6G, 12G. Câble long, verrouillable.</li><li><b>HDMI</b> : grand public, câble court, pas de verrouillage.</li></ul><h3>RAID</h3><ul><li><b>RAID 0</b> : répartition (vitesse), aucune sécurité.</li><li><b>RAID 1</b> : miroir (sécurité), capacité divisée par 2.</li><li><b>RAID 5</b> : parité, ≥ 3 disques, survit à 1 panne. <b>RAID 6</b> : 2 pannes.</li></ul><h3>Bonnes pratiques</h3><ol><li>Décharger les cartes avec <b>vérification checksum</b> (MD5, xxHash).</li><li>Appliquer la règle <b>3-2-1</b>.</li><li>Un RAID n’est pas une sauvegarde : il protège d’une panne de disque, pas d’une erreur humaine.</li></ol>`),
les("📖 5. Audio numérique",`<h3>Numériser le son</h3><p>L’<b>échantillonnage</b> mesure le signal à intervalles réguliers. D’après Nyquist, la fréquence maximale reproductible est la moitié de la fréquence d’échantillonnage : à 48 kHz, 24 kHz. La <b>quantification</b> (16 ou 24 bits) donne la précision : environ 6 dB de dynamique par bit, soit ≈ 96 dB en 16 bits et ≈ 144 dB en 24 bits.</p><h3>Niveaux</h3><ul><li><b>dBFS</b> : 0 dBFS est le maximum numérique ; on ne le dépasse jamais (clipping, distorsion irrécupérable).</li><li>Niveau de ligne (pro +4 dBu) beaucoup plus fort que niveau micro : préampli nécessaire.</li></ul><h3>Loudness</h3><p>Norme <b>EBU R128</b> (Europe) : −23 LUFS (±0,5 LU) et crête réelle maximale −1 dBTP. Les plateformes web visent souvent autour de −14 à −16 LUFS (à vérifier selon la plateforme).</p><h3>Micros et câbles</h3><ul><li><b>Dynamique</b> : robuste. <b>Statique</b> (à condensateur) : plus sensible, alimentation fantôme 48 V.</li><li>Directivités : omnidirectionnel, cardioïde, hypercardioïde (canon).</li><li>Liaison <b>XLR symétrique</b> : rejette les parasites sur longue distance.</li></ul>`),
les("📖 6. Timecode, synchronisation et colorimétrie",`<h3>Timecode</h3><p>Il numérote chaque image : HH:MM:SS:FF. À 25 i/s, pas de problème. À 29,97 i/s, le timecode compte 30 images par seconde et dérive : le <b>drop frame</b> saute les numéros 00 et 01 au début de chaque minute, sauf les minutes multiples de 10 (aucune image n’est supprimée, seulement des numéros).</p><ul><li><b>LTC</b> : timecode sur une piste audio. <b>Genlock</b> : synchronise le balayage des appareils (black burst, tri-level).</li></ul><h3>Espaces colorimétriques</h3><ul><li><b>Rec.709</b> : HD/SDR. <b>Rec.2020</b> : UHD, gamut étendu. <b>DCI-P3</b> : cinéma numérique. <b>sRGB</b> : web.</li><li>HDR : courbes <b>PQ</b> (ST 2084) et <b>HLG</b>, en 10 bits minimum.</li><li>Niveaux vidéo (limited 16–235 en 8 bits) vs niveaux data (full 0–255) : une confusion donne une image délavée ou écrasée.</li></ul><h3>Scopes</h3><ul><li><b>Waveform</b> : luminance. <b>Parade RVB</b> : équilibre des couches. <b>Vectorscope</b> : teinte et saturation (la ligne de peau).</li></ul>`),
les("📖 7. Le signal vidéo analogique : balayage, normes et bande passante",`<div class="note"><b>Remarque :</b> ce chapitre reprend le cours de stage ; les points rectifiés par rapport au cahier sont signalés.</div><h3>La persistance rétinienne</h3><p>Propriété de l’œil qui relie les images successives et crée l’illusion du mouvement. À partir d’environ <b>25 images par seconde (25 i/s)</b>, le mouvement paraît continu. Pour limiter le scintillement, la télévision renouvelle l’écran plus souvent grâce à l’entrelacement (voir ci-dessous).</p><h3>Le balayage entrelacé</h3><ul><li>Une image est décomposée en <b>deux trames</b> : la trame paire et la trame impaire, balayées l’une après l’autre.</li><li>Une image entière se nomme <b>frame</b> ; une trame se nomme <b>field</b>.</li><li>À 25 i/s, on obtient donc 50 trames par seconde (fréquence de trame : 50 Hz).</li></ul><h3>Comparaison des normes France et États-Unis</h3><div style="overflow-x:auto"><table><tr><th>Paramètre</th><th>France (625 lignes)</th><th>États-Unis (525 lignes)</th></tr><tr><td>Rapport d’aspect</td><td>4/3</td><td>4/3 (voir la remarque)</td></tr><tr><td>Nombre de lignes</td><td>625</td><td>525</td></tr><tr><td>Lignes actives</td><td>≈ 575</td><td>≈ 480</td></tr><tr><td>Images par seconde</td><td>25 i/s</td><td>30 i/s (29,97 en réalité)</td></tr><tr><td>Fréquence de trame</td><td>50 Hz</td><td>60 Hz (59,94 en réalité)</td></tr></table></div><div class="note"><b>À vérifier :</b> le cahier indique 16/9 pour le système américain. Or le système analogique à 525 lignes est lui aussi en 4/3 ; le 16/9 est apparu avec la haute définition. Confirmer avec l’enseignant.</div><h3>Le signal de ligne et la suppression</h3><ul><li>Une ligne comprend une partie <b>active</b> (l’image visible) et une zone de <b>suppression</b> (<i>blanking</i>).</li><li>La suppression sert à <b>masquer le retour du faisceau</b> vers le début de la ligne suivante.</li><li>En couleur, la zone de suppression porte aussi le <b>burst</b> : une courte salve de sous-porteuse qui sert de référence à la couleur.</li><li>Pour le système 625 lignes, environ 575 lignes sont actives : les 50 lignes restantes correspondent à la suppression verticale. Le nombre 1080 relève de la HD, non de ce système.</li></ul><h3>Modulation de fréquence et bande passante</h3><p>La <b>FM</b> est la modulation de fréquence. La <b>bande passante</b> est l’espace de fréquences nécessaire pour transmettre un signal.</p><h3>La bande passante théorique</h3><p><b>BP = (lignes × lignes × rapport d’aspect × fréquence d’image) ÷ 2</b></p><p>Le produit lignes × (lignes × rapport d’aspect) donne le nombre de points d’une image ; on le multiplie par le nombre d’images par seconde, puis on divise par 2 car deux points suffisent à décrire une période du signal.</p><p>Application pour 625 lignes, 4/3, 25 i/s : BP = (625 × 625 × 4/3 × 25) ÷ 2 ≈ <b>6,5 MHz</b>.</p><h3>Le rapport signal sur bruit</h3><p>Le <b>rapport S/N</b> compare le niveau du signal utile à celui du bruit ; il s’exprime en décibels (dB). Plus il est élevé, plus le signal est propre.</p>`),
les("📖 8. Luminance, chrominance et signaux de différence",`<h3>Les récepteurs de l’œil</h3><ul><li><b>Bâtonnets</b> : récepteurs sensibles à la lumière sans distinction de couleur (noir et blanc). Selon le cours, ils sont environ 4 fois plus sensibles que les cônes ; ce facteur est celui du cours, non une mesure universelle.</li><li><b>Cônes</b> : récepteurs responsables de la vision des couleurs, sensibles au rouge, au vert et au bleu (R, V, B).</li></ul><h3>Luminance et chrominance</h3><ul><li><b>Y (luminance)</b> : information de brillance, c’est-à-dire l’image en noir et blanc.</li><li><b>C (chrominance)</b> : information de couleur.</li></ul><h3>La formule de la luminance</h3><p><b>Y = 0,3 R + 0,59 V + 0,11 B</b></p><p>Pour un blanc (R = V = B = 1 V) : Y = 0,3 + 0,59 + 0,11 = <b>1 V</b>. Les coefficients traduisent la sensibilité de l’œil : très forte au vert, faible au bleu.</p><h3>Les signaux de différence de couleur</h3><p>On transmet Y, puis deux signaux de différence, <b>R − Y</b> (noté D<sub>R</sub>) et <b>B − Y</b> (noté D<sub>B</sub>). Le troisième, V − Y, se déduit des deux autres.</p><ol><li>Les coefficients de Y valent 1 au total, donc : 0,3 (R − Y) + 0,59 (V − Y) + 0,11 (B − Y) = 0.</li><li>On isole le terme en vert : 0,59 (V − Y) = − 0,3 (R − Y) − 0,11 (B − Y).</li><li>On divise par 0,59 : <b>V − Y = − 0,51 (R − Y) − 0,19 (B − Y)</b>.</li></ol><h3>Les formats de transmission</h3><div style="overflow-x:auto"><table><tr><th>Format</th><th>Principe</th></tr><tr><td><b>Composantes (Y, D<sub>R</sub>, D<sub>B</sub>)</b></td><td>Trois signaux transmis séparément.</td></tr><tr><td><b>Y/C</b></td><td>Luminance et chrominance transmises séparément, sur deux voies.</td></tr><tr><td><b>Composite</b></td><td>Luminance et chrominance mélangées sur un seul canal.</td></tr></table></div><h3>Module et phase de la chrominance</h3><p>Dans le plan (a, b) des deux signaux de différence, la chrominance est un vecteur :</p><ul><li><b>Module A = √(a² + b²)</b> : il donne la saturation.</li><li><b>Phase γ = tan⁻¹ (b ÷ a)</b> : elle donne la teinte.</li></ul>`),
les("📖 9. Barres de couleur, oscilloscope et vecteurscope",`<h3>La synthèse additive</h3><p>Les trois primaires <b>R, V, B</b> s’additionnent : R + V donne le <b>jaune</b>, V + B le <b>cyan</b>, R + B le <b>magenta</b>, et R + V + B le <b>blanc</b>. L’absence de lumière donne le noir.</p><h3>La mire de barres</h3><p>La mire comporte huit barres, dans l’ordre : <b>blanc, jaune, cyan, vert, magenta, rouge, bleu, noir</b>. On distingue la mire <b>EBU 100 %</b> (primaires à pleine amplitude) et la mire <b>EBU 75 %</b> (amplitude réduite, plus facile à transmettre sans dépassement).</p><div style="overflow-x:auto"><table><tr><th>Barre</th><th>Composition (niveaux 0 ou 1)</th></tr><tr><td>Blanc</td><td>R = 1, V = 1, B = 1</td></tr><tr><td>Jaune</td><td>R = 1, V = 1, B = 0</td></tr><tr><td>Cyan</td><td>R = 0, V = 1, B = 1</td></tr><tr><td>Vert</td><td>R = 0, V = 1, B = 0</td></tr><tr><td>Magenta</td><td>R = 1, V = 0, B = 1</td></tr><tr><td>Rouge</td><td>R = 1, V = 0, B = 0</td></tr><tr><td>Bleu</td><td>R = 0, V = 0, B = 1</td></tr><tr><td>Noir</td><td>R = 0, V = 0, B = 0</td></tr></table></div><h3>Le niveau de référence</h3><p>Le niveau du blanc est de <b>0,7 V</b> (valeur à confirmer sur le cours). C’est ce niveau qui est utilisé dans les calculs qui suivent.</p><h3>Exemple : la barre verte vue à l’oscilloscope</h3><p>Avec R = 0, V = 0,7 V et B = 0 :</p><ul><li><b>Y</b> = (0,3 × 0) + (0,59 × 0,7) + (0,11 × 0) = <b>0,413 V</b>.</li><li><b>D<sub>R</sub> = R − Y</b> = 0 − 0,413 = <b>− 0,413 V</b>.</li><li><b>D<sub>B</sub> = B − Y</b> = 0 − 0,413 = <b>− 0,413 V</b>.</li></ul><p>À l’oscilloscope, on observe trois paliers horizontaux : un niveau positif pour Y, deux niveaux négatifs égaux pour D<sub>R</sub> et D<sub>B</sub>.</p><h3>La chrominance de cette barre</h3><p>Avec a et b égaux en valeur absolue à 0,413 : <b>A = √(0,413² + 0,413²) ≈ 0,584</b>. Comme a et b ont la même valeur absolue, l’angle γ vaut 45° par rapport à l’axe horizontal ; les deux composantes étant négatives, le vecteur pointe vers le quadrant inférieur gauche.</p><h3>Le vecteurscope</h3><div style="overflow-x:auto"><table><tr><th>Lecture</th><th>Information</th></tr><tr><td><b>Distance à l’origine O</b></td><td>Saturation</td></tr><tr><td><b>Angle α du vecteur</b></td><td>Teinte</td></tr><tr><td><b>Au-delà du cercle</b></td><td>Couleur « super saturée » (saturation excessive)</td></tr></table></div><p>Les couleurs sont réparties autour du cercle (rouge, magenta, bleu, cyan, jaune…) ; une flèche courbe indique le sens de rotation de la teinte.</p>`),
les("📖 10. La caméra, l’objectif et les réglages d’exposition",`<h3>Le synoptique d’une tête de caméra</h3><ol><li><b>Bloc optique</b> : l’objectif forme l’image.</li><li><b>Bloc d’analyse et de traitement</b> : le capteur et l’électronique de traitement.</li><li><b>Bloc d’adaptation et de mise en forme</b> : il prépare le signal de sortie.</li></ol><h3>Caméras ENG et EFP</h3><div style="overflow-x:auto"><table><tr><th>Type</th><th>Caractéristiques</th></tr><tr><td><b>ENG</b> (<i>Electronic News Gathering</i>)</td><td>Caméra de reportage électronique ; enregistrement interne sur bande magnétique, disque optique, mémoire flash ou disque dur (HDD).</td></tr><tr><td><b>EFP</b> (<i>Electronic Field Production</i>)</td><td>Caméra de production électronique de terrain ; configuration lourde ou hybride ; liaisons possibles : fibre, triax, HF, 5G, satellite.</td></tr></table></div><h3>La composition d’un objectif</h3><p>De l’avant vers le capteur, la chaîne optique regroupe, entre autres, les éléments suivants ; plusieurs se règlent par des <b>bagues</b>.</p><ul><li><b>Mise au point (MAP)</b> : netteté de l’image.</li><li><b>Focale / zoom</b> : fait varier la focale, donc le cadrage.</li><li><b>Diaphragme</b> : contrôle la quantité de lumière.</li><li><b>Filtre optique</b> (par exemple ND, densité neutre).</li><li><b>Tirage optique</b> : réglage de la distance entre l’objectif et le capteur.</li></ul><h3>Le nombre d’ouverture</h3><p><b>n = f ÷ ∅</b>, où f est la focale et ∅ le diamètre d’ouverture, tous deux en millimètres.</p><p>Échelle : <b>f/1 – f/1,4 – f/2 – f/2,8 – f/4 – f/5,6 – f/8 – f/11 – f/16 – f/22</b>.</p><ul><li>Petit chiffre = grande ouverture ; grand chiffre = petite ouverture.</li><li>Passer à la valeur suivante en fermant divise la lumière par 2 ; en ouvrant, on la multiplie par 2.</li></ul><h3>La vitesse d’obturation</h3><p>Échelle : 1 s – 1/2 – 1/4 – 1/8 – 1/15 – 1/30 – 1/60 – 1/125 – 1/250 – 1/500 – 1/1000 – 1/2000 – 1/4000 – 1/8000.</p><p>D’un palier au suivant, le temps de pose est multiplié ou divisé par 2 (les valeurs affichées sont arrondies).</p><h3>La sensibilité ISO</h3><p>Échelle : <b>25 – 50 – 100 – 200 – 400 – 800 – 1600 – 3200 – 6400 – 12800 – 25600 – 51200 – 102400</b>. La valeur 100, absente du cahier, a été rétablie d’après l’échelle standard.</p><h3>Résumé</h3><div style="overflow-x:auto"><table><tr><th>Paramètre</th><th>Grandeur</th></tr><tr><td><b>Diaphragme</b></td><td>Nombre d’ouverture (f/…)</td></tr><tr><td><b>Vitesse d’obturation</b></td><td>Secondes</td></tr><tr><td><b>Sensibilité</b></td><td>ISO</td></tr></table></div>`),
les("📖 11. Évaluer des équipements : microphones, caméras et capteurs",`<h3>Les critères d’évaluation d’un microphone</h3><div style="overflow-x:auto"><table><tr><th>Critère</th><th>Ce qu’il décrit</th></tr><tr><td><b>Technologie</b></td><td>Dynamique ou à condensateur (statique).</td></tr><tr><td><b>Sensibilité</b></td><td>Niveau de sortie obtenu pour une pression acoustique donnée.</td></tr><tr><td><b>Directivité</b></td><td>Zone dans laquelle le micro capte le son (omnidirectionnel, cardioïde, hypercardioïde).</td></tr><tr><td><b>Réponse en fréquence</b></td><td>Plage de fréquences correctement restituée.</td></tr><tr><td><b>Rapport S/N</b></td><td>Rapport entre signal utile et bruit, en dB.</td></tr><tr><td><b>Alimentation fantôme</b></td><td>Alimentation (48 V) fournie par la console ou le préampli aux micros qui en ont besoin.</td></tr></table></div><h3>Les critères d’évaluation d’une caméra</h3><div style="overflow-x:auto"><table><tr><th>Critère</th><th>Ce qu’il décrit</th></tr><tr><td><b>Sensibilité</b></td><td>Capacité à produire une image correcte avec peu de lumière ; elle dépend du capteur.</td></tr><tr><td><b>Rapport S/N</b></td><td>Niveau de bruit de l’image par rapport au signal, en dB.</td></tr><tr><td><b>Résolution</b></td><td>Finesse de l’image, en lignes ou en pixels.</td></tr><tr><td><b>Taux de modulation</b></td><td>Contraste restitué pour les détails fins.</td></tr></table></div><h3>Les caractéristiques du capteur</h3><ul><li><b>Technologie</b> du capteur.</li><li><b>Taille</b> du capteur (voir le chapitre sur la caméra, le capteur et l’optique).</li><li><b>Nombre de pixels</b>.</li><li><b>Surface sensible</b>.</li></ul>`)
];

