COURS.ana.push(
["Mouvements de caméra",["Panoramique : rotation sur l’axe (caméra fixe). Travelling : déplacement de la caméra. Zoom : variation de focale sans déplacement.","Plan épaule, steadicam, grue, drone, plan-séquence.","Mise au point : pull focus / rack focus pour déplacer l’attention."]],
["Le son au cinéma",["Diégétique (dans l’univers du film) / extradiégétique (musique de fosse, voix off).","In (source visible), hors-champ, off.","Contrepoint : le son contredit l’émotion de l’image."]],
["Montage & récit",["Champ/contrechamp, montage alterné, montage parallèle, ellipse, flash-back.","Koulechov : le sens naît du rapprochement des plans. Eisenstein : montage des attractions. Bazin : plan-séquence et profondeur de champ.","Schéma narratif : situation initiale, élément perturbateur, péripéties, climax, dénouement."]],
["Repères historiques",["1895 : Lumière. 1902 : Méliès, Le Voyage dans la Lune. 1915 : Griffith. 1925 : Potemkine.","1927 : début du parlant. 1941 : Citizen Kane. 1945 : néoréalisme italien.","1959–1960 : Nouvelle Vague (Truffaut, Godard)."]]
);
LESSONS.ana=[
les("📖 1. Plans, angles et mouvements",`<h3>L’échelle des plans</h3><ul><li><b>Plan général / d’ensemble</b> : le décor domine, personnages minuscules.</li><li><b>Plan large</b> : situe l’action et l’environnement.</li><li><b>Plan moyen</b> : personnage en pied.</li><li><b>Plan américain</b> : à mi-cuisses (hérité du western).</li><li><b>Plan rapproché</b> : taille ou poitrine.</li><li><b>Gros plan</b> : visage, expression. <b>Très gros plan</b> : un détail (œil, bouche). <b>Insert</b> : objet.</li></ul><h3>Les angles</h3><ul><li><b>Neutre</b> (hauteur d’yeux), <b>plongée</b> (caméra au-dessus : souvent écrase ou fragilise), <b>contre-plongée</b> (caméra en dessous : souvent valorise, impose), <b>zénithal</b> (à la verticale), <b>cadre penché</b> (déséquilibre, malaise).</li></ul><p>Attention : ces effets sont des tendances, pas des lois. On interprète toujours en contexte.</p><h3>Les mouvements</h3><ul><li><b>Panoramique</b> : rotation horizontale ou verticale sur un axe. <b>Panoramique filé</b> : très rapide, image floue.</li><li><b>Travelling</b> : déplacement de la caméra (avant, arrière, latéral, circulaire). Zoom ≠ travelling : le zoom change la focale, le travelling change la perspective.</li><li><b>Plan-séquence</b> : une séquence entière en un seul plan.</li><li><b>Plan subjectif</b> : la caméra adopte le regard du personnage.</li></ul>`),
les("📖 2. Cadre, lumière, couleur et mise en scène",`<h3>Le cadre</h3><ul><li>Formats : 1,33 (4:3), 1,85, 2,39 (« scope »), 16:9 (1,78).</li><li><b>Champ</b> : ce qu’on voit. <b>Hors-champ</b> : ce qui est suggéré (un regard, un son) : source de suspense.</li><li>Composition : lignes, profondeur, symétrie, plans.</li></ul><h3>La lumière</h3><ul><li><b>High key</b> : éclairage uniforme, lumineux, peu de contraste (comédie, joie).</li><li><b>Low key</b> : fort contraste, zones d’ombre (thriller, film noir).</li><li><b>Clair-obscur</b> : contraste marqué lumière/ombre, héritage de la peinture.</li></ul><h3>La couleur</h3><p>Chaud/froid, saturation, dominante. La couleur peut être symbolique (rouge : passion, danger), mais l’analyse doit s’appuyer sur le film précis.</p><h3>La mise en scène</h3><p>Ensemble des choix visibles à l’écran : décor, costumes, jeu d’acteurs, placement dans le cadre, lumière, mouvements. Le <b>découpage</b>, lui, concerne la division de l’action en plans.</p>`),
les("📖 3. Le son au cinéma",`<h3>Les catégories</h3><ul><li><b>Diégétique</b> : appartient à l’univers de l’histoire (dialogue, bruits, musique jouée par un personnage). <b>Extradiégétique</b> : hors de cet univers (musique de fosse, voix off du narrateur).</li><li><b>In</b> : source visible. <b>Hors-champ</b> : source dans l’univers mais non visible. <b>Off</b> : source extérieure à l’espace de l’image.</li></ul><h3>Éléments d’une bande-son</h3><ul><li><b>Dialogues</b>, <b>bruitages</b> (Foley), <b>ambiances</b>, <b>effets</b>, <b>musique</b>, <b>silence</b>.</li></ul><h3>Effets expressifs</h3><ul><li><b>Pont sonore</b> : le son continue d’un plan à l’autre, liant les scènes (J-cut / L-cut).</li><li><b>Contrepoint</b> : son en décalage avec l’émotion visuelle (musique joyeuse sur une scène dramatique).</li><li><b>Leitmotiv</b> : thème musical associé à un personnage ou une idée.</li><li><b>Valeur ajoutée</b> et <b>synchrèse</b> (Michel Chion) : le son modifie la perception de l’image ; un son et une image simultanés sont perçus comme liés.</li></ul>`),
les("📖 4. Montage, récit et théories",`<h3>Types de montage</h3><ul><li><b>Champ/contrechamp</b> : alterne les personnages d’un dialogue.</li><li><b>Alterné</b> : deux actions simultanées (course-poursuite). <b>Parallèle</b> : deux actions liées par le thème, sans simultanéité.</li><li><b>Ellipse</b> : saut dans le temps. <b>Flash-back</b> : retour en arrière.</li></ul><h3>Théoriciens et courants</h3><ul><li><b>Griffith</b> : généralise le montage alterné.</li><li><b>Koulechov</b> : un même gros plan neutre prend un sens différent selon l’image qui le précède (effet Koulechov).</li><li><b>Eisenstein</b> : montage des attractions, conflit entre les plans (Le Cuirassé Potemkine, 1925).</li><li><b>Bazin</b> : défend le plan-séquence et la profondeur de champ (Welles, Renoir).</li><li><b>Nouvelle Vague</b> : jump cut assumé (Godard, À bout de souffle).</li></ul><h3>Le récit</h3><ul><li><b>Schéma narratif</b> : situation initiale → élément perturbateur → péripéties → climax → dénouement.</li><li><b>Structure en 3 actes</b> : exposition, confrontation, résolution.</li><li><b>Focalisation</b> : zéro (omniscient), interne (un personnage), externe (extérieur aux pensées).</li><li><b>Temps du récit</b> : ordre, durée, fréquence.</li></ul>`),
les("📖 5. Méthode d’analyse d’une séquence",`<h3>Rappel des unités</h3><p><b>Plan</b> : entre deux coupes. <b>Scène</b> : unité de lieu et de temps. <b>Séquence</b> : ensemble de plans/scènes formant une unité dramatique.</p><h3>Les étapes</h3><ol><li><b>Situer</b> : film, réalisateur, année, place de la séquence dans le récit.</li><li><b>Résumer</b> en 2–3 phrases ce qui se passe.</li><li><b>Découper</b> : tableau plan par plan (n°, échelle, angle, mouvement, durée, son, action).</li><li><b>Repérer les procédés</b> : cadrage, lumière, couleur, montage, son, jeu.</li><li><b>Dégager une problématique</b> : que cherche à produire la séquence ?</li><li><b>Rédiger</b> : introduction, 2–3 axes (chaque axe = procédé + exemple précis + interprétation), conclusion.</li></ol><div class="note"><b>Formule gagnante :</b> « procédé → exemple du film → effet sur le spectateur → sens ». Toute remarque technique doit déboucher sur une interprétation.</div><h3>Vocabulaire à utiliser</h3><p>Cadre, champ, hors-champ, découpage, raccord, ellipse, diégèse, focalisation, mise en scène, point de vue, rythme.</p>`),
les("📖 6. Repères d’histoire du cinéma",`<ul><li><b>1895</b> : les frères Lumière, cinématographe. Premières projections publiques payantes au Grand Café à Paris (28 décembre 1895).</li><li><b>1902</b> : Georges Méliès, <i>Le Voyage dans la Lune</i>, trucages, cinéma de spectacle.</li><li><b>1915</b> : Griffith, <i>Naissance d’une nation</i>, grammaire du montage (film controversé par son propos raciste, à replacer dans son contexte).</li><li><b>Années 1920</b> : expressionnisme allemand (<i>Le Cabinet du docteur Caligari</i>, 1920), montage soviétique (Eisenstein, <i>Potemkine</i>, 1925).</li><li><b>1927</b> : <i>Le Chanteur de jazz</i>, début du cinéma parlant.</li><li><b>Années 1930–40</b> : Hollywood classique et système des studios ; <i>Citizen Kane</i> (Welles, 1941), profondeur de champ et récit éclaté.</li><li><b>1945</b> : néoréalisme italien (Rossellini, <i>Rome, ville ouverte</i>) : décors réels, acteurs non professionnels.</li><li><b>1959–1960</b> : Nouvelle Vague (Truffaut, <i>Les Quatre Cents Coups</i> ; Godard, <i>À bout de souffle</i>).</li><li><b>Années 1970</b> : Nouvel Hollywood.</li><li><b>Depuis les années 2000</b> : cinéma numérique, effets visuels, plateformes de streaming et séries.</li></ul>`),
les("📖 7. L’échelle des plans : comparatif des sources",`<h3>Quatre colonnes de lecture</h3><p>Le tableau comparatif de l’annexe met en regard les définitions de <b>Vincent Pinel</b> (<i>Vocabulaire technique du cinéma</i>, 1996), leur équivalent anglais, et celles de deux sources américaines : <b>Ira Konigsberg</b> (<i>The Complete Film Dictionary</i>, 1997) et <b>Bordwell et Thompson</b> (<i>Film Art</i>, 3<sup>e</sup> éd., 1990).</p><div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:.92em"><tr><th style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Plan (Pinel)</th><th style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Équivalent anglais (Pinel)</th><th style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Konigsberg</th><th style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Bordwell / Thompson</th></tr><tr><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top"><b>Plan général</b> : vaste ensemble qui situe le décor construit dans son cadre</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Extreme long shot</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Paysage ou décor vu à très grande distance</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">La figure humaine est à peine visible</td></tr><tr><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top"><b>Plan d’ensemble</b> : cadre l’ensemble du décor construit</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Long shot</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Personnages intégrés à un environnement qui reste prépondérant</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">—</td></tr><tr><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top"><b>Plan américain</b> : coupe les personnages à mi-cuisse</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">« Plan américain » (traduit par <i>medium close shot</i>)</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">—</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Personnage cadré à partir des genoux</td></tr><tr><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top"><b>Plan demi-ensemble</b> ou <b>plan large</b> : personnages dans leur milieu, avec une bonne partie du décor</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Medium long shot</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Synonyme de plan américain</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Même distance que le plan américain, mais avec un objet plutôt qu’un corps</td></tr><tr><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top"><b>Plan moyen</b> : personnages en pied</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Full shot</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Non mentionné</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">—</td></tr><tr><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top"><b>Plan rapproché taille</b> ou <b>plan taille</b></td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Medium shot</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">—</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Personnage cadré à partir de la taille</td></tr><tr><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top"><b>Plan rapproché</b> (poitrine) : personnage(s) au niveau de la poitrine</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Medium close-up</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Personnage cadré à mi-poitrine (<i>medium close shot</i>)</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Figure cadrée à partir de la poitrine</td></tr><tr><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top"><b>Gros plan</b> : isole un visage (à hauteur du nœud de cravate), un autre détail du corps, ou un petit objet</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Close-up</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Tête et épaules du personnage, ou une partie du corps</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Le plan montre seulement la tête, les mains, les pieds ou un petit objet</td></tr><tr><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top"><b>Très gros plan</b> : une partie du visage ou un détail du corps (œil, bouche, doigt…)</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Extreme close-up</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">—</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Le plan isole une partie du visage, un petit objet ou un détail</td></tr></table></div><h3>À retenir</h3><ul><li>Les termes français et anglais ne se recouvrent pas toujours : le « plan américain » n’a pas d’équivalent direct en anglais, et Pinel le traduit par <i>medium close shot</i>.</li><li>Trois plans gardent le personnage entier ou presque : <b>américain</b> (mi-cuisse), <b>moyen</b> (en pied) et <b>demi-ensemble</b>. Il faut savoir distinguer leur coupe.</li><li>Dans une analyse, nommer le plan avec le terme du cours, puis préciser son effet (proximité, isolement, situation dans le décor).</li></ul><h3>Insert et plan de coupe</h3><ul><li>L’<b>insert</b> est un plan de détail inséré au montage à l’intérieur d’une séquence ; chez Pinel, il se définit surtout par l’échelle (un très gros plan qui découpe une partie d’un corps ou d’un objet).</li><li>Le <b>plan de coupe</b> assure la liaison entre deux plans et la continuité de l’un à l’autre.</li><li>Dans les deux cas, le plan présente un caractère intrusif au sein de la séquence : c’est ce qui permet de les repérer.</li></ul>`),
les("📖 8. Analyser un film et le situer dans l’histoire des formes",`<h3>Situer le film</h3><p>Analyser un film, c’est aussi le situer dans un <b>contexte</b> : courants, écoles esthétiques, influences. Le cinéma emprunte au roman, à la peinture, au théâtre et à la musique. Certains cinéastes s’inscrivent dans la modernité européenne (Bergman, Fellini, Godard, Wenders, Carax) ; d’autres se réfèrent à leurs prédécesseurs par la citation, le pastiche, la parodie ou l’hommage.</p><h3>Le cinéma des premiers temps (vers 1900–1908)</h3><ul><li>Les films tiennent souvent en <b>un seul plan</b> (une « vue »), sans découpage.</li><li>Noël Burch (<i>Le Cinéma américain</i>, 1980) parle de <b>non-continuité</b> pour caractériser ce cinéma « primitif ».</li><li>Traits repérables : <b>non-homogénéité</b> (films construits par tableaux, séparés par de grandes ellipses), <b>non-clôture</b> (copies vendues, coupées, remontées par les exploitants) et <b>non-linéarité</b> (chevauchements temporels, une scène reprise d’un plan à l’autre).</li><li>Ces traits viennent des spectacles de l’époque : lanterne magique, cirque, music-hall, vaudeville, théâtre populaire. Ils ne relèvent pas de la maladresse.</li></ul><h3>La mise en place de la continuité narrative</h3><ul><li>On attribue souvent à <b>D. W. Griffith</b> le mérite d’avoir élaboré la forme de récit qui sert de modèle au <b>classicisme hollywoodien</b>, à partir des années 1915.</li><li>Cette forme repose sur un mode de production rationalisé : division du travail dans les grands studios (scénario, découpage, tournage, montage).</li><li>La continuité narrative, qui structure le produit-film, permet de suivre l’histoire sans rupture.</li></ul><h3>Application</h3><p>Dans un commentaire, on distingue le cinéma de la <b>continuité</b> (classique) des films qui s’en écartent (non-linéarité, faux raccords assumés, récit éclaté), puis on interprète ce choix formel.</p>`),
les("📖 9. Étude de séquence : l’ouverture d’<i>Alien</i> (Ridley Scott, 1979)",`<p>Exemple d’application de la méthode d’analyse d’une séquence, d’après l’analyse de la séquence d’introduction proposée par le Café des images.</p><h3>1. Un vaisseau hanté</h3><ul><li><b>Forme</b> : un travelling arrière découvre le <i>Nostromo</i> sur le mode de l’exploration ; la caméra se déplace ensuite de façon autonome dans les coursives.</li><li><b>Effet</b> : la caméra incarne une présence fantomatique et annonce la circulation furtive de l’Alien.</li><li><b>Ambiance</b> : musique minimaliste, vaisseau silencieux et désert, signes indirects de présence (battements de cœur sous l’échographie, objet qui oscille, pages agitées par un courant d’air, ordinateur qui s’allume, diodes rouges).</li><li><b>Fin de séquence</b> : l’emballement de l’ordinateur de bord, en plans fixes sur l’écran et son reflet dans le casque d’urgence (champ/contrechamp), annonce un péril imminent.</li></ul><h3>2. La renaissance des astronautes</h3><ul><li><b>Forme</b> : lent travelling jusqu’à la chambre d’hibernation, cadrage solennel ; décor blanc aux motifs octogonaux, cellules en forme de pétales.</li><li><b>Effet</b> : une naissance métaphorique ; la scénographie hiératique évoque un temple précolombien et donne une dimension spirituelle à la scène.</li><li><b>Montage</b> : des fondus enchaînés montrent Kane qui sort de l’hypersommeil ; les ellipses visibles traduisent la douceur et la progressivité de l’éveil.</li></ul><h3>3. Interprétation</h3><ul><li>Le film a pour thème la phobie de la reproduction biologique, représentée de façon horrifique par l’Alien.</li><li>Le réveil des astronautes, lui, est montré par une métaphore végétale, comme un processus asexué voire spirituel : le <i>Nostromo</i> est le monde du progrès technique (« Mother » est un ordinateur), l’Alien celui du principe vital violent et répugnant.</li><li>La comparaison avec l’éclosion du facehugger est révélatrice : même lumière bleue, même musique d’introduction, mais une éclosion mise en scène comme une agression (<i>jump scare</i>).</li></ul><div class="note"><b>Réflexe d’analyse</b> : toujours enchaîner « procédé → exemple du film → effet sur le spectateur → sens », et relier une scène à une autre pour gagner en profondeur.</div>`),
les("📖 10. Le barème de l’épreuve d’analyse filmique",`<p>La grille de l’exercice « comprendre les compétences de la matière » (BTS AV1) répartit les points ainsi :</p><table style="width:100%;border-collapse:collapse;font-size:.92em"><tr><th style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Compétence</th><th style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Barème</th></tr><tr><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Qualité de la syntaxe</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">/2</td></tr><tr><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Richesse du vocabulaire</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">/2</td></tr><tr><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Méthodologie</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">/4</td></tr><tr><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Vocabulaire technique</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">/3</td></tr><tr><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Sens de l’analyse : profondeur, finesse, originalité</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">/7</td></tr><tr><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Réinvestissement des éléments du cours</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">/2</td></tr><tr><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">Culture générale, artistique et audiovisuelle</td><td style="border:1px solid var(--bd);padding:6px 8px;vertical-align:top">/2</td></tr></table><h3>Ce que cela implique</h3><ul><li>Le critère le plus lourd est le <b>sens de l’analyse</b> (7 points) : profondeur, finesse, originalité. C’est là que se joue la note.</li><li>La <b>méthodologie</b> (4 points) et le <b>vocabulaire technique</b> (3 points) se travaillent : méthode d’analyse d’une séquence et étude d’<i>Alien</i>, termes de « Plans, angles et mouvements » et de « L’échelle des plans ».</li><li>Le <b>réinvestissement du cours</b> et la <b>culture audiovisuelle</b> valent 2 points chacun : citer des films, des auteurs, des repères.</li><li>La syntaxe et la richesse du vocabulaire (2 points chacune) se gagnent par une rédaction soignée.</li></ul><div class="note">Selon la lecture de la feuille, le total est de 20 points (sans le réinvestissement, noté entre parenthèses) ou de 22 avec lui : à vérifier avec l’enseignant.</div>`)
];

/* chapitres du programme (référentiel « Culture audiovisuelle et artistique ») : l'analyse filmique y regroupe les leçons ci-dessus */
