COURS.adobe.push(
["Photoshop avancé",["Modes de fusion : Produit (assombrit), Écran (éclaircit), Incrustation, Lumière tamisée.","Masque d’écrêtage : limite un calque à la forme du calque inférieur.","Remplissage selon contenu, tampon, correcteur : retouche."]],
["After Effects : les bases",["Raccourcis : P position, S échelle, R rotation, T opacité, A point d’ancrage, U propriétés animées.","F9 : Easy Ease. Éditeur de graphes : vitesse / valeur.","Ctrl+Shift+C : pré-composer."]],
["Incrustation & compositing",["Fond vert : éclairage uniforme, sujet éloigné du fond pour limiter la contamination (spill).","Keylight : clé, puis nettoyage des bords (choke), suppression du spill.","Cohérence : lumière, couleur, grain, flou, ombres."]],
["Intégration Premiere / Media Encoder",["Dynamic Link : Premiere ↔ After Effects sans export intermédiaire.","Media Encoder : file de rendu en arrière-plan (H.264, ProRes…).","Transparence : ProRes 4444, PNG, TIFF."]]
);
LESSONS.adobe=[
les("📖 1. Photoshop : calques, masques et retouche",`<h3>Types de calques</h3><ul><li><b>Pixels</b>, <b>texte</b>, <b>forme</b> (vectoriel), <b>réglage</b> (correction non destructive appliquée aux calques en dessous), <b>objet dynamique</b> (conserve les données source : transformations et filtres réversibles).</li></ul><h3>Masques</h3><ul><li><b>Masque de fusion</b> : le <b>blanc révèle</b>, le <b>noir masque</b>, les gris donnent la transparence partielle. On ne supprime aucun pixel.</li><li><b>Masque d’écrêtage</b> : limite un calque à la forme du calque inférieur.</li><li><b>Sélectionner un sujet / Sélectionner et masquer</b> : détourage assisté, à affiner sur les cheveux.</li></ul><h3>Modes de fusion</h3><ul><li><b>Produit</b> (assombrit, le blanc disparaît), <b>Écran</b> (éclaircit, le noir disparaît), <b>Incrustation / Lumière tamisée</b> (contraste), <b>Couleur</b>, <b>Luminosité</b>.</li></ul><h3>Retouche</h3><ul><li><b>Tampon de duplication</b>, <b>correcteur</b>, <b>pièce</b>, <b>remplissage selon contenu</b>. Retoucher sur un calque vide ou dupliqué.</li></ul><h3>Raccourcis utiles</h3><p><b>Ctrl+J</b> dupliquer le calque, <b>Ctrl+T</b> transformation, <b>Ctrl+Z</b> / <b>Ctrl+Alt+Z</b> annuler plusieurs fois.</p><div class="note"><b>Principe :</b> travailler de façon non destructive (calques de réglage, masques, objets dynamiques).</div>`),
les("📖 2. After Effects : compositions, calques et animation",`<h3>Structure</h3><ul><li><b>Projet</b> : médias importés. <b>Composition</b> : définition, fréquence, durée. <b>Calques</b> : vidéo, solide, forme, texte, <b>calque de réglage</b>, <b>objet nul</b>, caméra, lumière.</li></ul><h3>Propriétés de transformation</h3><p><b>A</b> point d’ancrage, <b>P</b> position, <b>S</b> échelle, <b>R</b> rotation, <b>T</b> opacité. <b>U</b> affiche les propriétés animées, <b>UU</b> celles qui ont été modifiées.</p><h3>Animation</h3><ul><li><b>Keyframes</b> (images clés) : le logiciel interpole entre elles.</li><li><b>Interpolation</b> : linéaire, Bézier, maintenue. <b>F9 = Easy Ease</b> (accélération/décélération douce).</li><li><b>Éditeur de graphes</b> : courbes de valeur et de vitesse.</li><li><b>Parenting</b> : un calque enfant hérite des transformations du parent (hors opacité).</li><li><b>Pré-composition</b> (Ctrl+Shift+C) : regroupe des calques dans une composition imbriquée, pour organiser et appliquer un effet à l’ensemble.</li></ul><h3>Expressions</h3><p><code>wiggle(2,30)</code> : variation aléatoire, 2 fois par seconde, amplitude 30. <code>loopOut()</code> : boucle d’animation. <code>time</code> : temps en secondes.</p><h3>Rendu</h3><p>Fichier → Exporter → Ajouter à la file de Media Encoder (H.264, ProRes…). Éviter le rendu direct pour les formats de diffusion.</p>`),
les("📖 3. Incrustation, détourage et compositing",`<h3>Tourner pour incruster</h3><ul><li>Fond <b>vert</b> (ou bleu) <b>uniformément éclairé</b>, sans plis.</li><li>Sujet <b>éloigné du fond</b> (1,5 à 3 m) pour éviter la <b>contamination (spill)</b> verte.</li><li>Éclairer le sujet séparément, avec une lumière cohérente avec le décor final.</li><li>Pas de vert dans les vêtements ; éviter le flou de bougé excessif.</li></ul><h3>La clé dans After Effects</h3><ol><li><b>Keylight</b> : sélectionner la couleur d’écran, ajuster Screen Gain, Clip Black / White.</li><li>Nettoyer avec un <b>masque poubelle (garbage matte)</b> pour les bords du fond.</li><li>Affiner : <b>choke</b>, <b>feather</b> des bords.</li><li><b>Suppression du spill</b> : neutraliser les reflets verts.</li></ol><h3>Détourage</h3><ul><li><b>Masques</b> à la plume, <b>Roto Pinceau</b> (rotoscopie assistée), <b>mattes</b> : Alpha Matte (utilise la transparence du calque au-dessus), Luma Matte (utilise sa luminosité).</li></ul><h3>Intégrer un élément</h3><ul><li>Même direction et qualité de lumière, même balance colorimétrique, même <b>grain</b>, même profondeur de champ (flou), ombres et reflets.</li><li><b>Suivi de mouvement (tracking)</b> 2D ou 3D pour coller un élément à la caméra.</li></ul>`),
les("📖 4. Premiere Pro, Media Encoder et chaîne de production",`<h3>Premiere Pro</h3><ul><li><b>Séquence</b> : paramètres (résolution, 25 i/s en Europe…) ; on peut créer une séquence à partir du premier clip.</li><li>Outils : <b>V</b> sélection, <b>C</b> rasoir, <b>Ctrl+K</b> couper à la tête de lecture, <b>I/O</b> marques d’entrée/sortie, <b>,</b> insérer, <b>.</b> écraser.</li><li><b>Lumetri Color</b> : étalonnage. <b>Graphiques essentiels</b> : titres animés.</li><li><b>Proxys</b> : montage fluide sur médias lourds.</li></ul><h3>La chaîne Adobe</h3><ul><li><b>Dynamic Link</b> : remplacer par une composition After Effects sans export intermédiaire.</li><li><b>Media Encoder</b> : file d’attente d’exports en arrière-plan, préréglages de diffusion.</li><li>Formats avec transparence : <b>ProRes 4444</b>, <b>PNG</b>, <b>TIFF</b>.</li></ul><h3>Bonnes pratiques</h3><ol><li>Nommer, trier, organiser les médias.</li><li>Garder les originaux intacts.</li><li>Exporter un master puis les versions de diffusion.</li></ol>`)
];

